from candidate import is_palindrome
import pytest
from unittest.mock import patch

@pytest.mark.parametrize("text, expected", [
    ("", True),
    ("aba", True),
    ("aaaaa", True),
    ("zbcd", False),
])
def test_is_palindrome_normal_cases(text, expected):
    assert is_palindrome(text) == expected

def test_is_palindrome_with_special_characters(text):
    assert is_palindrome("a.b.c.a") == True
    assert is_palindrome("a,b,c") == False

def test_is_palindrome_with_mixed_case(text):
    assert is_palindrome("Abacaba") == True
    assert is_palindrome("Abcba") == True
    assert is_palindrome("abc") == False

def test_is_palindrome_with_non_alpha_numbers(text):
    assert is_palindrome("A man, a plan, a canal: Panama") == True
    assert is_palindrome("Not a palindrome") == False

def test_is_palindrome_with_mixed_case_and_symbols(text):
    assert is_palindrome("!dlroW ,olleH") == True
    assert is_palindrome("Hello, World!") == False

@pytest.mark.parametrize("text", [
    (" ", " "),  # Palindrome edge case with only spaces
    ("a", "a"),  # Single character edge case
    ("ab", "ab"),  # Non-palindrome edge case with two characters
])
def test_is_palindrome_single_and_two_characters(text):
    assert is_palindrome(text) is True if text == text[::-1] else is_palindrome(text) is False

def test_is_palindrome_with_larger_strings(text):
    assert is_palindrome("A" * 1000) == True
    assert is_palindrome("A" * 999 + "b") == False

@pytest.mark.parametrize("text", [
    ("", None),
    ("", False),
])
def test_is_palindrome_none_and_false_inputs(text):
    with pytest.raises(TypeError):
        is_palindrome(text)

def test_is_palindrome_with_empty_string(text):
    assert is_palindrome("") == True

@pytest.mark.parametrize("text", [
    ("", "a"),
    ("ab", "a"),
])
def test_is_palindrome_with_none_too_short(text):
    with pytest.raises(ValueError):
        is_palindrome(text)

def test_is_palindrome_with_mixed_types(text):
    with pytest.raises(TypeError):
        is_palindrome(None)
    with pytest.raises(TypeError):
        is_palindrome(False)
    with pytest.raises(TypeError):
        is_palindrome(123)
    with pytest.raises(TypeError):
        is_palindrome([1, 2, 3])
